const item = $input.first().json;
const msg = (item.messages && item.messages[0]) || {};
const contact = (item.contacts && item.contacts[0]) || {};

const from = msg.from || '';
const name = (contact.profile && contact.profile.name) || '';
const type = msg.type || 'unknown';

let text = '';
let mediaNote = '';
if (type === 'text') {
  text = (msg.text && msg.text.body) || '';
} else if (type === 'button') {
  text = (msg.button && msg.button.text) || '';
} else if (type === 'interactive') {
  const inter = msg.interactive || {};
  text = (inter.button_reply && inter.button_reply.title) || (inter.list_reply && inter.list_reply.title) || '';
} else {
  text = '[' + type + ' message]';
  mediaNote = 'media type: ' + type;
}

const isText = type === 'text' && text.trim().length > 0;

// Convert WhatsApp epoch seconds to ISO if present
let msgTimestamp = new Date().toISOString();
if (msg.timestamp) {
  const secs = parseInt(msg.timestamp, 10);
  if (!isNaN(secs)) msgTimestamp = new Date(secs * 1000).toISOString();
}

return [{
  json: {
    sender_phone: from,
    sender_name: name,
    msg_type: type,
    text: text || '(empty message)',
    is_text: isText,
    media_note: mediaNote,
    msg_timestamp: msgTimestamp,
  },
}];

const norm = $('Normalize Message').item.json;
const exRaw = $('Extract Intent').item.json;
const ex = exRaw.output ? exRaw.output : exRaw;
const empRaw = $('Lookup Employee').item.json || {};
const emp = (empRaw && Object.keys(empRaw).length > 0) ? empRaw : null;

const ALLOWED = ['Late Arrival','Half Day','Sick Leave','Full-Day Leave','Advance Request','Overtime','Other'];
let intent = (ex && ex.intent ? String(ex.intent) : '').trim();
if (!ALLOWED.includes(intent)) intent = norm.is_text ? 'Unknown' : 'Other';

let amount = ex && ex.amount != null ? ex.amount : '';
if (amount !== '' && isNaN(Number(amount))) amount = '';

// Default event_date to today in Asia/Karachi
let eventDate = ex && ex.event_date ? String(ex.event_date).trim() : '';
if (!eventDate) {
  const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Karachi' }));
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  eventDate = y + '-' + m + '-' + d;
}

const notesParts = [];
if (ex && ex.note) notesParts.push(String(ex.note));
if (norm.media_note) notesParts.push(norm.media_note);
if (!emp) notesParts.push('unmatched sender');
if (intent === 'Unknown') notesParts.push('could not classify - ask to rephrase');

return [{
  json: {
    timestamp: new Date().toISOString(),
    employee_id: emp ? (emp.employee_id || '') : '',
    employee_name: emp ? (emp.employee_name || norm.sender_name || '') : (norm.sender_name || ''),
    source: 'whatsapp',
    raw_text: norm.text,
    intent: intent,
    amount: amount,
    event_date: eventDate,
    status: 'pending',
    notes: notesParts.join(' | '),
    // carried for reply, not stored
    _sender_phone: norm.sender_phone,
  },
}];
